<?php
require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_keuangan']);
$page_title='Input RAB';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$training=trim($_POST['training_name']??'');$date=$_POST['budget_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');$descs=$_POST['description']??[];$qtys=$_POST['quantity']??[];$units=$_POST['unit']??[];$prices=$_POST['unit_price']??[];
if($title){try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO rabs(title,training_name,budget_date,notes,created_by) VALUES(?,?,?,?,?)');$q->execute([$title,$training?:null,$date,$notes?:null,$_SESSION['user']['id']]);$id=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO rab_items(rab_id,description,quantity,unit,unit_price) VALUES(?,?,?,?,?)');foreach($descs as $i=>$desc){$desc=trim((string)$desc);$qty=(float)($qtys[$i]??0);$price=(float)($prices[$i]??0);if($desc!==''&&$qty>0&&$price>=0)$item->execute([$id,$desc,$qty,trim((string)($units[$i]??''))?:null,$price]);}$pdo->commit();flash('RAB berhasil disimpan.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('RAB gagal disimpan. Periksa data dan database.');}}else flash('Judul RAB wajib diisi.');header('Location: rab.php');exit;}
$rows=$pdo->query("SELECT r.id,r.title,r.training_name,r.budget_date,COALESCE(SUM(i.quantity*i.unit_price),0) total FROM rabs r LEFT JOIN rab_items i ON i.rab_id=r.id GROUP BY r.id ORDER BY r.created_at DESC")->fetchAll();require __DIR__.'/includes/header.php';show_flash();
?>
<section class="panel"><div class="panel-head"><h3>Buat Rencana Anggaran Biaya</h3></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Judul RAB *</label><input name="title" required placeholder="Contoh: RAB Bimtek SIPD"></div><div class="field"><label>Nama kegiatan</label><input name="training_name"></div><div class="field"><label>Tanggal RAB</label><input type="date" name="budget_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Catatan</label><input name="notes"></div></div><h3 style="margin-top:22px">Rincian anggaran</h3><div class="table-wrap"><table><thead><tr><th>Uraian</th><th>Volume</th><th>Satuan</th><th>Harga satuan (Rp)</th></tr></thead><tbody><?php for($i=0;$i<6;$i++):?><tr><td><input name="description[]" placeholder="Uraian biaya"></td><td><input name="quantity[]" type="number" min="0" step="0.01" value="1"></td><td><input name="unit[]" placeholder="orang/paket"></td><td><input name="unit_price[]" type="number" min="0" step="1000" value="0"></td></tr><?php endfor;?></tbody></table></div><div class="form-actions"><button class="btn">Simpan RAB</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Daftar RAB</h3></div><table><thead><tr><th>Judul</th><th>Kegiatan</th><th>Tanggal</th><th>Total Anggaran</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="empty">Belum ada RAB.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['training_name']?:'-')?></td><td><?=e($r['budget_date'])?></td><td><strong>Rp <?=number_format((float)$r['total'],0,',','.')?></strong></td></tr><?php endforeach;endif;?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php';?>
